

DROP TABLE IF EXISTS cbc_countries CASCADE;
CREATE TABLE cbc_countries (recid CHARACTER VARYING(35) PRIMARY KEY, json_data JSON);

DROP TABLE IF EXISTS cbc_provinces CASCADE;
CREATE TABLE cbc_provinces (recid CHARACTER VARYING(35) PRIMARY KEY, json_data JSON);

DROP TABLE IF EXISTS cbc_districts CASCADE;
CREATE TABLE cbc_districts (recid CHARACTER VARYING(35) PRIMARY KEY, json_data JSON);

DROP TABLE IF EXISTS cbc_communes CASCADE;
CREATE TABLE cbc_communes (recid CHARACTER VARYING(35) PRIMARY KEY, json_data JSON);

DROP TABLE IF EXISTS cbc_villages CASCADE;
CREATE TABLE cbc_villages (recid CHARACTER VARYING(35) PRIMARY KEY, json_data JSON);

DROP TABLE IF EXISTS cbc_list_values CASCADE;
CREATE TABLE cbc_list_values (recid CHARACTER VARYING(35) PRIMARY KEY, json_data JSON);













CREATE OR REPLACE VIEW vw_cbc_countries AS
SELECT
	recid::TEXT AS id_country,
	COALESCE(json_data->>'c2', '') AS code2,
	COALESCE(json_data->>'c2', '') AS code3,
	COALESCE(json_data->>'c3', '') AS full_name
FROM cbc_countries;

CREATE OR REPLACE VIEW vw_cbc_provinces AS
SELECT
	recid::TEXT AS id_province,
	COALESCE(json_data->>'c1', '') AS full_name,
	COALESCE(json_data->>'c2', '') AS full_name_kh
FROM cbc_provinces;

CREATE OR REPLACE VIEW vw_cbc_districts AS
SELECT
	LEFT(recid, 2)::TEXT AS id_province,
	recid::TEXT AS id_district,
	COALESCE(json_data->>'c1', '') AS full_name,
	COALESCE(json_data->>'c2', '') AS full_name_kh
FROM cbc_districts;

CREATE OR REPLACE VIEW vw_cbc_communes AS
SELECT
	LEFT(recid, 2)::TEXT AS id_province,
	LEFT(recid, 4)::TEXT AS id_district,
	recid::TEXT AS id_commune,
	COALESCE(json_data->>'c1', '') AS full_name,
	COALESCE(json_data->>'c2', '') AS full_name_kh
FROM cbc_communes;

CREATE OR REPLACE VIEW vw_cbc_villages AS
SELECT
	LEFT(recid, 2)::TEXT AS id_province,
	LEFT(recid, 4)::TEXT AS id_district,
	LEFT(recid, 6)::TEXT AS id_commune,
	recid::TEXT AS id_village,
	COALESCE(json_data->>'c1', '') AS full_name,
	COALESCE(json_data->>'c2', '') AS full_name_kh
FROM cbc_villages;

CREATE OR REPLACE VIEW vw_cbc_list_values AS
SELECT
    recid::TEXT AS recid,
    COALESCE(json_data->>'c1', '') AS group_1,
    COALESCE(json_data->>'c2', '') AS group_2,
    COALESCE(json_data->>'c3', '') AS group_3,
    COALESCE(json_data->>'c4', '') AS val_code,
    COALESCE(json_data->>'c5', '') AS narrative
FROM cbc_list_values;





